app.js

```jsx
import { createSSRApp } from "vue";

// 之所以要将创建Vue应用的方法提取出来
// 是因为在服务端渲染和客户端渲染的时候，都需要创建一个Vue应用实例
export function createApp() {
  // 创建一个Vue应用实例
  const app = createSSRApp({
    template: `
        <div>
            <h1>Hello SSR</h1>
            <p>{{message}}</p>
            <button @click="count++">{{ count }}</button>
        </div>
    `,
    data: () => ({
      count: 1,
      message: "这是一个SSR最简单的demo",
    }),
  });
  return app;
}
```



