import { createApp } from "./app.js";
createApp().mount("#app");
```



server.js

```javascript
import { renderToString } from "vue/server-renderer";
import express from "express";
import fs from "fs";
import { createApp } from "./app.js";

// 创建服务器实例
const server = express();

// 定义一个配置对象，配置页面的元数据信息
const desc = {
  title: "SSR demo",
  meta: '<meta name="description" content="这是一个SSR最简单的demo">',
};

server.get("/", async (req, res) => {
  try {
    // 根据vue实例渲染出来的字符串内容
    const app = createApp();
    const content = await renderToString(app);
    const template = fs.readFileSync("./index.html", "utf-8");
    const html = template
      .replace("<!--title-->", desc.title)
      .replace("<!--meta-->", desc.meta)
      .replace("<!--vue-ssr-outlet-->", content);
    res.send(html);
    // 读取模板文件
  } catch (err) {
    console.log(err);
    res.status(500).send("服务器内部错误");
  }
});

// 使用中间件
// 将当前目录作为静态资源服务器目录
server.use(express.static("."));

server.listen("3000", () => {
  console.log("服务器已启动，监听3000端口......");
});

```



用node启动服务器，当浏览器请求页面的时候：

1.服务器先准备好.html模板文件和需要替换的内容

2.利用vue提供的createSSRApp和renderToString的方法，在服务器端渲染好静态页面

3.为了让静态页面能运行js，还需要在模板文件中准备好client.js，后续的操作要交给他来处理

## csr项目改造成ssr
1.改造router

SSR 环境，每一次请求都必须要是全新的路由实例

```javascript
export function createRouter() {
  return _createRouter({
    history: createMemoryHistory,
    routes
  })
}
```



2. 改造入口文件

要做的事情和改造router 一致，单独导出一个方法来创建应用实例

```vue
export function createApp() {
  // 创建Vue应用实例，这里使用createSSRApp
  const app = createSSRApp(App)
  // 创建路由实例
  const router = createRouter()
  const pinia = createPinia()

  // 引入图标
  for (const [key, component] of Object.entries(ElementPlusIconsVue)) {
    app.component(key, component)
  }
  app.use(router).use(pinia).use(ElementPlus)
  // 需要将这些实例返回给外部
  return { app, router, pinia }
}
```



3. 服务器端入口文件

导出一个方法，该方法会根据传入的 url 做对应的首屏渲染

```javascript
// 服务器端入口文件
import { createApp } from '../main'
import { renderToString } from 'vue/server-renderer'

/**
 *
 * @param {*} url 用户请求的url
 * 根据不同的url，返回不同的首屏内容
 */
export async function render(url) {
  const { app, router } = createApp()

  // 根据用户请求的url，跳转到对应的路由
  router.push(url)

  // 等待路由跳转完成
  await router.isReady()

  // 目前为止，说明咱们的应用已经跳转到了对应的页面
  // 接下来需要对这个页面进行服务器端渲染，渲染为字符串
  const html = renderToString(app)
  return [html]
}
```

> 是一个入口文件，给express服务器提供渲染后的html
>



4. 创建服务器

```javascript
import express from 'express'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

// 辅助方法
import { createRequire } from 'module'
const require = createRequire(import.meta.url)
// 拿到当前文件的目录路径
const __dirname = path.dirname(fileURLToPath(import.meta.url))
// 定义 resolve 函数，用于拼接绝对路径
const resolve = (p) => path.resolve(__dirname, '..', p)

export async function createServer() {
  // 1. 创建 express 应用
  const app = express()

  // 2. 将 vite 创建的服务器以中间件的形式添加到 express 应用中，从而能够使用 vite 的热模块更新等特性
  const vite = await require('vite').createServer({
    server: {
      middlewareMode: true
    },
    appType: 'custom'
  })
  app.use(vite.middlewares)

  // 3. 处理请求
  app.use('*', async (req, res, next) => {
    try {
      // 拿到请求的 url
      const url = req.originalUrl
      // 读取出来的模板html文件的字符串
      let template = fs.readFileSync(resolve('index.html'), 'utf-8')
      // 调用 vite 的 transformIndexHtml 方法，注入一些必要的脚本和样式，为了使用 vite 的热更新等特性
      template = await vite.transformIndexHtml(url, template)
      // 读取服务端入口文件拿到 render 方法
      const render = (await vite.ssrLoadModule('/src/entry/server-entry.js')).render
      // 拿到的是Vue应用的html字符串
      const [appHtml] = await render(url)
      // 接下来做替换操作
      const html = template.replace(`<!--vue-ssr-outlet-->`, appHtml)
      console.log(html, 'html')
      // 返回给客户端
      res.status(200).set({ 'Content-Type': 'text/html' }).end(html)
    } catch (error) {
      vite.ssrFixStacktrace(error)
      console.error(error)
      res.status(500).send('Server Error')
      next()
    }
  })

  return app
}
```

