    startTop = 0, // 要滑动的元素默认的 top 值
    movePointY = 0; // 手指移动时的坐标
// 这里我们用到了腾讯的第三方库 transform，通过 Transform(DOM节点) 进行一个初始化
// 之后我们就可以非常方便的获取以及设置该 DOM 节点和 transform 相关的属性值
Transform(list);
console.log(list.translateY);
