### 上拉刷新与下拉加载更多
可用swiper的库

```javascript
var mySwiper = new Swiper(".swiper-container", {
  direction: "vertical",
  scrollbar: ".swiper-scrollbar",
  slidesPerView: "auto",
  mousewheelControl: true,
  freeMode: true,
  // 用户在整个轮播图上面滑动时
  onTouchMove: function () {
    if (mySwiper.translate < 50 && mySwiper.translate > 0) {
      $(".init-loading").html("下拉刷新...").show();
    } else if (mySwiper.translate > 50) {
      $(".init-loading").html("释放刷新...").show();
    }
  },
  // 滑动结束时
  onTouchEnd: function () {
    var _viewHeight =
      document.getElementsByClassName("swiper-wrapper")[0].offsetHeight;
    var _contentHeight =
      document.getElementsByClassName("swiper-slide")[0].offsetHeight;

    // 根据滑动的距离判断是刷新还是加载

    // 上拉加载
    if (
      mySwiper.translate <= _viewHeight - _contentHeight - 100 &&
      mySwiper.translate < 0
    ) {
      if (loadFlag) {
        $(".loadtip").html("正在加载...");
        // 模仿异步加载数据
        setTimeout(function () {
          for (var i = 0; i < 5; i++) {
            oi++;
            $(".list-group")
              .eq(mySwiper2.activeIndex)
              .append(
                '<li class="list-group-item">我是加载出来的' + oi + "...</li>"
              );
          }
          $(".loadtip").html("上拉加载更多...");
          mySwiper.update(); // 重新计算高度;
          // 上拉加载到一定数据则不能再加载
          if (oi >= 20) {
            loadFlag = false;
          }
        }, 800);
      } else {
        $(".loadtip").html("没有更多啦！");
      }
    }

    // 下拉刷新
    if (mySwiper.translate >= 50) {
      $(".init-loading").html("正在刷新...").show();
      $(".loadtip").html("上拉加载更多");
      // 模仿异步加载数据
      setTimeout(function () {
        $(".refreshtip").show();
        $(".init-loading").html("刷新成功！");
        if (oj <= 5) {
          for (var i = 0; i < 5; i++) {
            oj++;
            $(".list-group")
              .eq(mySwiper2.activeIndex)
              .prepend(
                '<li class="list-group-item">我是新增数据' + oj + "...</li>"
              );
          }
        }

        setTimeout(function () {
          $(".init-loading").html("").hide();
        }, 800);
        $(".loadtip").show();

        //刷新操作
        mySwiper.update(); // 重新计算高度;
      }, 1000);
    } else if (mySwiper.translate >= 0 && mySwiper.translate < 50) {
      $(".init-loading").html("").hide();
    }
    return false;
  },
});
