  const buildDir = join(distDir, `client-${version}`);
  await copyDirectory(sourceDir, buildDir);
  await zipFolder(buildDir, join(distDir, `client-${version}.zip`));
  await rm(buildDir, { recursive: true });
  console.log('打包完成');
}

